@import url("im_design_system/v1.0.0/css/common.css");

.form-area {
  border-radius: 4px;
}

@media screen and (max-width: 768px) {
  .form-area > div > div {
    padding-left: 1.5rem !important;
    padding-right: 1.5rem !important;
    margin-top: 1.5rem !important;
  }
}

/* color */
.select-color {
  position: relative;
  outline: 2px solid #fff;
  outline-offset: -4px;
}

.select-color::after {
  content: "";
  display: block;
  position: absolute;
  top: 0.6rem;
  left: 0.5rem;
  width: 1rem;
  height: 0.65rem;
  border-left: 3px solid #fff;
  border-bottom: 3px solid #fff;
  transform: rotate(-45deg);
}

.radio {
  cursor: pointer;
}

.radio > input {
  visibility: hidden;
}

.action-item {
  cursor: pointer;
}

/* card */
.holiday-user-card {
  background: #ccc;
  border-radius: 4px;
}

.holiday-name-area {
  display: flex;
  justify-content: flex-end;
}

.holiday-name {
  border-radius: 2px;
  overflow-wrap: break-word;
}

.holiday-user-id {
  opacity: 0.85;
  overflow-wrap: anywhere;
}

/* padding reset */
.im-hichee-container.im-hichee-production-mode .holiday-user-card div {
  padding: 0;
}

.im-hichee-container.im-hichee-production-mode .holiday-user-card {
  min-width: 12rem;
}

/* for designer mode */
.im-hichee-container.im-hichee-designer-mode .holiday-user-card {
  min-width: 500px;
}

/* refer */
.refer-mode .field input,
.refer-mode .field .user-name,
.refer-mode .field .holiday-name {
  border-bottom: 1px solid #eee;
  margin-bottom: 0.5em;
}

.refer-mode .field .user-name,
.refer-mode .field .holiday-name {
  min-width: 6em;
  max-width: 100%;
  padding-bottom: calc(0.5em - 1px);
  overflow-wrap: break-word;
}

.holiday-list-item {
  display: flex;
}

.textarea[readonly] {
  border-color: #dbdbdb;
  box-shadow: none;
}

